data_contract.table:
id bigIncrements;
work_order_id FK work_orders, cascadeOnDelete, index;
kind string(20) NOT NULL — consultancy | institution;
supplier_id FK registries nullable, nullOnDelete — solo institution;
payment_method_id FK payment_methods nullable, nullOnDelete — snapshot dall'offerta;
status string(20) NOT NULL default 'pending', index — pending | issued;
issued_at timestamp nullable;
note text NOT NULL;
assigned_to FK users, restrictOnDelete; assigned_by FK users, restrictOnDelete;
timestamps. Indici: (work_order_id, status), created_at.
